// ============================================
// MINILAND - PARSER CSV + CLASIFICACIÓN
// ============================================

const csvText = $input.first().binary.data.toString('utf-8');
const lines = csvText.split(/\r?\n/);

// ===== UTILIDADES =====
function slugify(str) {
  return String(str || "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

function cleanText(str) {
  if (!str) return "";
  return String(str).normalize("NFC").trim();
}

function norm(str) {
  return cleanText(str)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function parseCSVLine(line) {
  const fields = [];
  let currentField = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"') {
      if (inQuotes && line[i + 1] === '"') {
        currentField += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === ',' && !inQuotes) {
      fields.push(currentField);
      currentField = "";
    } else {
      currentField += char;
    }
  }
  fields.push(currentField);
  return fields;
}

// ===== CLASIFICADOR =====
function classifyProduct(name, description) {
  const text = norm(name + " " + description);

  // BEBÉ / PUERICULTURA
  if (text.match(/bebe|lactancia|biberon|chupete|humidificador|termometro.*digital|vigilabebes|cuna|cambiador/)) {
    return { c: "bebe", s: "Puericultura", g: null, t: null };
  }

  // JUGUETES EDUCATIVOS
  if (text.match(/juego|puzzle|construccion|bloques|encajable|apilable|juguete/)) {
    return { c: "juguetes", s: "Educativos", g: null, t: null };
  }

  // FIGURAS / ANIMALES
  if (text.match(/figura.*animal|animales.*figura|dinosaurio|insecto|granja/)) {
    return { c: "juguetes", s: "Figuras", g: null, t: null };
  }

  // VEHÍCULOS
  if (text.match(/coche|vehiculo|tractor|camion|minimobil/)) {
    return { c: "juguetes", s: "Vehículos", g: null, t: null };
  }

  // MATERIAL ESCOLAR / EDUCATIVO
  if (text.match(/didactico|educativo|matematicas|numeros|letras|aprendizaje/)) {
    return { c: "material-escolar", s: "Didáctico", g: null, t: null };
  }

  // MANUALIDADES / ARTE
  if (text.match(/manualidades|pintura|plastilina|modelado|arte/)) {
    return { c: "material-escolar", s: "Manualidades", g: null, t: null };
  }

  // DEFAULT: Sin clasificar
  return { c: "sin-clasificar", s: "Miniland pendiente", g: null, t: null };
}

// ===== PROCESAR CSV =====
const products = [];

// Saltar header (línea 1)
for (let i = 2; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;

  const fields = parseCSVLine(line);

  // Mapeo de columnas (basado en el CSV)
  const entityId = cleanText(fields[0]);
  const name = cleanText(fields[42]);  // columna "name"
  const price = parseFloat(fields[48]) || 0;  // columna "price"
  const ean = cleanText(fields[51]);  // columna "product_ean"
  const sku = cleanText(fields[60]);  // columna "sku"
  const description = cleanText(fields[8]);  // columna "description"
  const image = cleanText(fields[21]);  // columna "image"

  if (!sku || !name) continue;

  const skuInterno = `M${sku}`;
  const slug = `${slugify(name)}-${slugify(skuInterno)}`;

  // Clasificar producto
  const cats = classifyProduct(name, description);

  // URL imagen completa
  const imagenes = image ? [`https://minilandgroup.com/pub/media/catalog/product${image}`] : [];

  products.push({
    json: {
      proveedor: "miniland",
      ref_proveedor: sku,
      sku_interno: skuInterno,
      name,
      description,
      precioBase: price,
      price: price,  // Se aplicará margen en siguiente nodo
      ean: ean || null,
      imagenes,
      slug,
      stock: 999,  // Por defecto hasta confirmar con Miniland
      categoryId: cats.c,
      subcategory: cats.s,
      grupo: cats.g,
      tipo_producto: cats.t,
      published: true,
      activo: true,
      visible_web: false  // CRÍTICO: oculto por defecto
    }
  });
}

return products;

// ============================================
// APLICAR MÁRGENES DINÁMICOS
// ============================================

function roundUp(price) {
  return Math.ceil(price * 2) / 2;
}

function calcularPrecioConMargen(precioBase) {
  const precio = parseFloat(precioBase);
  if (isNaN(precio) || precio <= 0) return { precioBase: 0, precioFinal: 0 };

  let multiplicador;
  if (precio < 50) multiplicador = 1.50;
  else if (precio < 100) multiplicador = 1.47;
  else if (precio < 200) multiplicador = 1.43;
  else if (precio < 400) multiplicador = 1.38;
  else multiplicador = 1.30;

  const precioConIva = precio * 1.21;

  return {
    precioBase: parseFloat(precio.toFixed(2)),
    precioFinal: roundUp(precioConIva * multiplicador)
  };
}

const results = [];
for (const item of $input.all()) {
  const precioOriginal = item.json.precioBase;
  const precios = calcularPrecioConMargen(precioOriginal);

  results.push({
    json: {
      ...item.json,
      precioBase: precios.precioBase,
      price: precios.precioFinal
    }
  });
}

return results;
